        console.log(obj.matrixWorldAutoUpdate); // false
        // 手动更新世界矩阵
        obj.position.set(10, 0, 0);
        obj.updateMatrixWorld();



    /* ------ [全局启用自动更新世界矩阵] ------------------------------------------- */ 
        // 全局启用自动更新世界矩阵
