        obj.rotateOnWorldAxis(new THREE.Vector3(0, 1, 0), Math.PI / 4);
        // 第三次: 绕世界坐标系中的自定义轴 (1, 1, 0) 旋转 60°
        const axis = new THREE.Vector3(1, 1, 0).normalize(); // 必须归一化
        obj.rotateOnWorldAxis(axis, Math.PI / 3);

    /* ------ [在动画中连续旋转] ------------------------------------------- */ 
        const obj = new THREE.Object3D();
        function animate() {
          requestAnimationFrame(animate);
          // 每帧绕世界坐标系中的 y 轴旋转 0.01 弧度
          obj.rotateOnWorldAxis(new THREE.Vector3(0, 1, 0), 0.01);
          renderer.render(scene, camera);
        }
        animate();
