        // 自定义 UV 生成器
        const customUVGenerator = {
          generateTopUV: function(geometry, vertices, indexA, indexB, indexC) {
            const a = vertices[indexA];
            const b = vertices[indexB];
            const c = vertices[indexC];
            
            return [
              new THREE.Vector2(a.x, a.y),
              new THREE.Vector2(b.x, b.y),
              new THREE.Vector2(c.x, c.y)
            ];
          },
          
          generateSideUV: function(geometry, vertices, indexA, indexB, indexC, indexD) {
            const a = vertices[indexA];
            const b = vertices[indexB];
            const c = vertices[indexC];
            const d = vertices[indexD];
            
            return [
              new THREE.Vector2(a.x, a.z),
              new THREE.Vector2(b.x, b.z),
              new THREE.Vector2(c.x, c.z),
              new THREE.Vector2(d.x, d.z)
            ];
          },
          
          generateBottomUV: function(geometry, vertices, indexA, indexB, indexC) {
            const a = vertices[indexA];
            const b = vertices[indexB];
            const c = vertices[indexC];
            
            return [
              new THREE.Vector2(a.x, a.y),
              new THREE.Vector2(b.x, b.y),
              new THREE.Vector2(c.x, c.y)
            ];
          }
        };

        const shape = new THREE.Shape();
        shape.moveTo(0, 0);
        shape.lineTo(2, 0);
        shape.lineTo(2, 1);
        shape.lineTo(0, 1);
        shape.lineTo(0, 0);

        const geometry = new THREE.ExtrudeGeometry(shape, {
          depth: 1,
          uvGenerator: customUVGenerator  // 使用自定义 UV 生成器
        });
