    /* 目标: 适合在资产加载后批量挂载，统一管理不同类型模型的阴影行为。 */
    function attachDistanceShadowMaterial(mesh, {
      alphaMap = null,
      alphaTest = 0.5,
      displacementMap = null,
      displacementScale = 1.0,
      displacementBias = 0.0
    } = {}) {
      const m = new THREE.MeshDistanceMaterial({
        alphaMap,
        alphaTest,
        displacementMap,
        displacementScale,
        displacementBias
      });

      mesh.castShadow = true;
      mesh.customDistanceMaterial = m;

      return m;
    }
